function isMatted() { return pagetype == "matted"; }
function isCard() { return pagetype == "card"; }
function isSpread() { return pagetype == "spreads"; }

function pages2spreads(state) {
	var spreads = {};
	for (var idx in state) {
		var s = pagefmt(Math.ceil(parseInt(idx, 10) / 2));
		console.log("s = " + s);
		if (!(s in spreads))
			spreads[s] = { "photos": [], "template": [], "bg": "ffffff", styles: [] };
		for (var i = 0; i < state[idx]["template"].length; i++) {
			var img = state[idx]["photos"][i];
			var tpl = state[idx]["template"][i];
			img["dx"] /= 2;
			img["sw"] /= 2;
			spreads[s]["photos"].push(img);
			spreads[s]["styles"].push(null);
			if (parseInt(idx, 10) % 2 == 0)
				spreads[s]["template"].push({ t: tpl.t, l: 50 + tpl.l / 2, w: tpl.w / 2, h: tpl.h, z: tpl.z });
			else
				spreads[s]["template"].push({ t: tpl.t, l: tpl.l / 2, w: tpl.w / 2, h: tpl.h, z: tpl.z });
		}
	}
	return spreads;
}

// split state of spreads to state of pages (twice as many): 0001 -> { 0001, 0002 }, 0002 -> { 0003, 0004}, ...
function spreads2pages(state) {
	var pages = {};
	for (idx in state) {
		var p1 = pagefmt(-1 + 2 * parseInt(idx, 10));
		var p2 = pagefmt(2 * parseInt(idx, 10));
		pages[p1] = { "photos": [], "template": [] };
		pages[p2] = { "photos": [], "template": [] };
		for (var i = 0; i < state[idx]["template"].length; i++) {
			var img = state[idx]["photos"][i];
			var tpl = state[idx]["template"][i];
			if (tpl["l"] < 50) {
				pages[p1]["photos"].push(img);
				pages[p1]["template"].push({ t: tpl.t, l: 2 * tpl.l, w: tpl.w * 2, h: tpl.h, z: tpl.z });
			} else {
				pages[p2]["photos"].push(img);
				pages[p2]["template"].push({ t: tpl.t, l: 2 * (tpl.l - 50), w: tpl.w * 2, h: tpl.h, z: tpl.z });
			}
		}
	}
	return pages;
}

