	/**
	  *
	  *  Utility functions
	  *
	  */


	function isCover(name) { return (name == "Kover" || name == "Cover"); }
	function hasCover() { return ("Cover" in bookstate || "Kover" in bookstate); }

	function nrspreads(state) {
		var n = Object.keys(state).length;
		if ("Kover" in state || "Cover" in state)
			n = n - 1;
		return n;
	}

	function nextPerm(array) {
		var r = nextPerm2(array);
		if (!r)
			array.reverse();
	}

	// NB 1: doesn't work for array of length 2 (returns false, hence nextPerm above)
	// NB 2: this is tailor made for cimg arrays (with a .src field)
	function nextPerm2(array) {
		// Find non-increasing suffix
		var i = array.length - 1;
		while (i > 0 && array[i - 1].src >= array[i].src)
			i--;
		if (i <= 0)
			return false;

		// Find successor to pivot
		var j = array.length - 1;
		while (array[j].src <= array[i - 1].src)
			j--;
		var temp = array[i - 1];
		array[i - 1] = array[j];
		array[j] = temp;

		// Reverse suffix
		j = array.length - 1;
		while (i < j) {
			temp = array[i];
			array[i] = array[j];
			array[j] = temp;
			i++;
			j--;
		}
		return true;
	}




	function shuffleArray(array) {
		for (var i = array.length - 1; i > 0; i--) {
			var j = Math.floor(Math.random() * (i + 1));
			var temp = array[i];
			array[i] = array[j];
			array[j] = temp;
		}
	}


	// arrayRotate(['h','e','l','l','o']);       => ['e','l','l','o','h'];
	// arrayRotate(['h','e','l','l','o'], true); => ['o','h','e','l','l'];
	function arrayRotateOne(arr, reverse) {
		if (reverse)
			arr.unshift(arr.pop())
		else
			arr.push(arr.shift())
		return arr
	}

	// if arr = [3, 4, 5, 9, 12, 28] and e = 9 then return [9, 12, 28, 3, 4, 5] = [9] ++ [12, 28] ++ [3, 4, 5]
	function pivotAround(arr, e) {
		var i = arr.indexOf(e);
		if (i == -1)
			return arr;
		var first = arr.slice(0, i);
		var second = arr.slice(i + 1);
		var third = second.concat(first);
		third.unshift(e);
		return third;
	}

	function insideRect(x1, y1, x2, y2, x, y) {
		//	console.log("x1, y1, x2, y2 = " + x1 + ", " + y1 + ", " + x2 + ", " + y2 + " -- x, y = " + x + ", " + y);
		return (x1 < x && x < x2 && y1 < y && y < y2);
	}

	// return index i of photo "name" on spread idx s.t. bookstate[idx]["photos"][i].src == name
	function photoIndex(name, idx) {
		var i = -1;
		for (var k = 0; k < bookstate[idx]["photos"].length; k++) {
			if (name == bookstate[idx]["photos"][k].src)
				i = k;
		}
		return i;
	};


	function deepCopyPhotos(spread) {
		var cimg = spread["photos"];
		var cp = [];
		for (var i = 0; i < cimg.length; i++) {
			var cpe = {};
			for (var e in cimg[i])
				cpe[e] = cimg[i][e];
			cp.push(cpe);
		}
		return cp;
	}

	function deepCopyText(spread) {
		if (!spread || !spread["text"])
			return [];
		var ctxt = spread["text"];
		var cp = [];
		for (var i = 0; i < ctxt.length; i++) {
			var cpe = {};
			for (var e in ctxt[i])
				cpe[e] = ctxt[i][e];
			cp.push(cpe);
		}
		return cp;
	}

	function basename(path) {
		return decodeURIComponent(path.split('/').reverse()[0]);
	}

	function basename_nosuffix(path) {
		var s = path.split('/').reverse()[0];
		return s.substr(0, s.lastIndexOf('.'));
	}



	function remove(array, element) {
		const index = array.indexOf(element);
		array.splice(index, 1);
	}

	function drawCircle(context, x, y, radius) {
		context.beginPath();
		context.arc(x, y, radius, 0, 2 * Math.PI, false);
		context.fillStyle = 'orange'; // 'rgba(0, 255, 0, 1)';
		context.fill();
		context.lineWidth = 3;
		context.strokeStyle = '#222';
		//  context.strokeStyle = '#eee';
		context.stroke();
	}

	function drawCenterText(context, x, y, txt, fontsize) {
		context.font = fontsize + 'pt Helvetica';
		context.textAlign = 'center';
		//	context.fillStyle = 'white';
		context.fillStyle = 'black';
		context.fillText(txt, x, y);
	}


	$.fn.swapWith = function (that) {
		var $this = this;
		var $that = $(that);

		// create temporary placeholder
		var $temp = $("<div>");

		// 3-step swap
		$this.before($temp);
		$that.before($this);
		$temp.after($that).remove();

		return $this;
	}

	function countInArray(array, what) {
		return array.filter(item => item == what).length;
	}

	function updateUsed() {
		// construct a list of used photos 
		var used = [];
		var skeys = Object.keys(bookstate);
		for (var i = 0; i < skeys.length; i++) {
			var cimg = bookstate[skeys[i]]["photos"];
			for (var j = 0; j < cimg.length; j++)
				used.push(cimg[j].src);
		}
		// mark each thumbnail as used or not
		$(".thumbnail").each(function () {
			var src = basename($(this).find('img').attr("src"));
			var c = countInArray(used, src);
			if (c == 0)
				$(this).removeClass("used").removeClass("usedtwice");
			else if (c == 1)
				$(this).addClass("used").removeClass("usedtwice");
			else if (c == 2)
				$(this).addClass("usedtwice").removeClass("used");
			if (c > 0)
				$(this).addClass("dimmed");
			else
				$(this).removeClass("dimmed");
			if (-1 != $.inArray(src, selected)) {
				$(this).addClass("gallery-selected");
			}
		});
	}

