			beforeOpen: function () {
				// note: animateModal src code has been modified to set global variable modalActive
				var spreadidx = spreadnr(modalActive.parent());
				editSpread(spreadidx);
				$("#editspread").show();
				backupstate = copyState(bookstate);
			},
			afterOpen: function () { },
			// beforeClose: function() { console.log("The animation was called"); }, 
