	function spreadbgcolor() {
		var color = $(".global-bg-color").val();
		if (!$("#pref-global-bg")[0].checked)
			color = "ffffff";
		return color;
	}

	function mknewspread(dontscroll) {
		$(".autolayout").hide();
		var newspread = $("#spread-template").clone();

		if (!preferences["gutter"])
			newspread.find('.guide').hide();
		newspread.removeAttr('id');
		var items = grid.getItems();
		var spreadidx = pagefmt(items.length + 1);
		newspread.attr("data-spread", spreadidx);
		newspread.find('.spread-title').text(spreadidx);
		var color = spreadbgcolor();
		newspread.css({ "display": "inline" });
		newspread.find('.spread').css({ "background": "#" + color });
		resizeCaption();
		grid.add([newspread[0]]);
		mkdroppable(newspread);
		setupHandlers(newspread);
		setSpreadSize(spreadidx);
		grid.refreshItems().layout();
		if (!dontscroll)
			newspread[0].scrollIntoView(false);
		setCurrentSpread(spreadidx);
		return spreadidx;
	}

	function handleUndo() {
		if ($("#undo-btn").hasClass("disabled"))
			return;
		undoHistory();
		populate();
	}

	function handleRedo() {
		if ($("#redo-btn").hasClass("disabled"))
			return;
		redoHistory();
		populate();
	}

	function handleNewSpread() {
		pushHistory("New spread");
		spreadidx = mknewspread();
		var color = spreadbgcolor();
		bookstate[spreadidx] = { photos: [], template: [], bg: color, text: [], styles: [] };
		if (isCard() || (isMatted() && $("#grid").children().length % 2)) {
			spreadidx = mknewspread();
			bookstate[spreadidx] = { photos: [], template: [], bg: color, text: [], styles: [] };
		}
	}

	$("#new-spread-btn").click(function () {
		if (isCard())
			return;
		handleNewSpread();
	});

	function doSave(k) {
		var savestate = bookstate;
		if (isMatted())
			savestate = pages2spreads(bookstate);

		$.post("./scripts/close-designer.php", {
			"bookstate": JSON.stringify(savestate),
			"albumid": albumid,
		}).done(function (msg) {
			if (-1 != msg.indexOf("ERROR"))
				alert(msg);
			else {
				swal('Album saved', 'A new version of this album was saved.', 'success');
				setTimeout(function () {
					swal.close();
					localStorage['RAD-bookstate'] = "";
					console.log(localStorage['RAD-bookstate']);
				}, 1000);
				if (k)
					k();
			}
		});
	}


	$("#save-btn").click(function () {
		doSave();
	});

	$("#quit-btn").click(function () {
		doSave(function () {
			window.opener.postMessage("foobar", "*");
			window.open('', '_self').close();
		});
	});

	var photogrid;

	function imagesLoaded() {

		photogrid = new Muuri('.photogrid', {
			dragEnabled: true,
			dragReleaseDuration: 0,
			dragReleaseEasing: '',
			dragContainer: document.body,
			//	dragSort: function () { return [grid, photogrid] }
		})
			// drag photo from photobucket to spread
			.on('dragEnd', function (item, event) {
				// drag from photobucket to spread
				// if event.type == "draginitup", the photo was clicked 
				// if event.type == "dragend", the photo was dragged, either within our out of bucket

				/*
						console.log('dragEnd');
						console.log(event);
						console.log("type = ");
						pprint(event.type);
						console.log(item._element);
				*/

				var targetSpread;
				var dx = $("#grid").offset().left;
				var dy = $(window).scrollTop();
				$(".spread-div").each(function () {
					var po = $(this).offset();
					var w = $(this).width();
					var h = $(this).height();
					if (insideRect(po.left, po.top, po.left + w, po.top + h, event.center.x, event.center.y + dy))
						targetSpread = $(this);
				});
				if (!targetSpread) {
					// user click on photo in the bucket, OR dragged it within photobucket
					if (event.type == "draginitup") {
						// user clicked on a photo in the photobucket
						var photo = $(item._element);
						handleAddNext(photo.find('img'));
					}
					return;
				}
				var photo = $(item._element);
				var photoname = basename(photo.find('img').attr("src"));
				var photow = photo.find('img')[0].naturalWidth;
				var photoh = photo.find('img')[0].naturalHeight;
				var targetidx = spreadnr(targetSpread);
				pushHistory("Add photo");
				addPhotoToBookState(targetidx, photoname, photow, photoh);
				// clear cache for matching templates for source and target
				bookstate[targetidx].matchingtpls = undefined;
				if (rematch(targetidx)) {
					populateSpread(targetidx, true);
					// $(item._element).addClass("used");
					updateUsed();
					setTimeout(function () { photogrid.refreshItems().layout(); }, 500);
				} else {
					handleUndo();
				}
				return true;
			});

		scaleSpreads(4);

	}

	$(".spread > .thumbnail").each(function () {
		$(this).addClass("photo");
	});

