	function photoBucket() {
		if (photosShowing) {
			$("#photobucket").parent().css({ "display": "inline" });
			$("#grid").parent().removeClass("col-12").addClass("col-8");
			$("#photos-btn").html("<span class='fa fa-eye-slash'></span>");
			$("#swapgrid-btn").show();
		} else {
			$("#photobucket").parent().css({ "display": "none" });
			$("#grid").parent().removeClass("col-8").addClass("col-12");
			$("#photos-btn").html("<span class='fa fa-eye'></span>");
			$("#swapgrid-btn").hide();
		}

		setTimeout(function () {
			scaleSpreads();
			grid.refreshItems().layout();
		}, 100);
		setTimeout(function () { photogrid.refreshItems().layout(); }, 100);
	}

	// galleryfirst == true means show gallery selected photos first
	var galleryfirst = false;
	$("#gallery-selected-btn").click(function () {
		if (!galleryfirst) {
			// move gallery selected photos to ip=0, 1, 2, etc
			galleryfirst = true;
			var photos = photogrid.getItems();
			var ip = 0;
			for (var i = 0; i < photos.length; i++) {
				var p = $(photos[i]._element);
				var src = basename(p.find('img').attr("src"));
				if (-1 != $.inArray(src, selected)) {
					photogrid.move(i, ip++);
				}
			}
		} else {
			// display photos in the $thumbs order
			galleryfirst = false;
			photogrid.sort(function (pa, pb) {
				var srca = basename($(pa._element).find('img').attr("src"));
				var srcb = basename($(pb._element).find('img').attr("src"));
				if (srca < srcb)
					return -1;
				else if (srca > srcb)
					return +1;
				else
					return 0;
			});
		}
		photogrid.refreshItems().layout();
	});


