	function fly(first, idx, delay) {
		var spreadDOM = $(".spread-div[data-spread=" + idx + "]");
		var src = first.offset();
		var dest = spreadDOM.offset();
		var destw = spreadDOM.find('.spread').width();
		var desth = spreadDOM.find('.spread').height();
		var srcw = first.width();
		var srch = first.height();
		var c = first.clone();
		$("#animation").append(c);
		c.show();
		c.css({ position: "fixed", left: src.left, top: src.top, "z-index": 9999 });
		c.animate({
			position: 'fixed',
			top: dest.top + desth / 2 - srch / 2,
			left: dest.left + destw / 2 - srcw / 2,
			transform: ''
		}, delay);
		setTimeout(function () {
			c.remove();
		}, delay);
	}

