	function autoadd1(photoname, spreadidx, delay, j, nitems) {
		var photo = findTN(photoname);
		photo[0].scrollIntoView(false);
		if (photo) {
			fly(photo, spreadidx, delay * (j + 1));
			setTimeout(function () { automkspread(spreadidx, photo); }, delay * (j + 1));
		}
	}

	// recursive function to auto layout photos in autospreds[i]  
	function autolayout(i, n, autospreads) {
		if (i >= n)
			return;
		var delay = preferences["animation"] ? 200 : 0;
		var nitems = autospreads[i].length;
		var spreadidx = mknewspread();
		var spreadDOM = $(".spread-div[data-spread=" + spreadidx + "]");
		spreadDOM[0].scrollIntoView(false);
		setTimeout(function () {
			bookstate[spreadidx] = { photos: [], template: [], bg: "ffffff", text: [], styles: [] };
			var photos = {};
			for (var j = 0; j < nitems; j++)
				autoadd1(autospreads[i][j], spreadidx, delay, j, nitems);
		}, delay);
		setTimeout(function () { autolayout(i + 1, n, autospreads); }, delay * (nitems + 2));
	}

