	function handleAddNext(photo) {
		var delay = preferences["animation"] ? 500 : 0;
		// if delay is too large, a fast user can add photos faster than the undo stack can register
		// if gallery selected photos appear first, pick from these first
		if (galleryfirst && !photo)
			photo = $(".gallery-selected").not(".used").first().find('img');
		// if gallery selected photos don't appear first, or if we've used all the gallery selected photos, pick next
		if (!photo || !photo.length)
			photo = $(".thumbnail").not(".used").first().find('img');
		// if all used up, return
		if (!photo || !photo.length)
			return;
		var targetidx = pagefmt($("#grid").children().length);
		if (targetidx == "0000") {
			console.log("no spread");
			return;
		}
		if (lastAddedSpread != -1)
			targetidx = pagefmt(lastAddedSpread);
		var photoname = basename(photo.attr("src"));
		var photow = photo[0].naturalWidth;
		var photoh = photo[0].naturalHeight;
		pushHistory("Add photo");
		addPhotoToBookState(targetidx, photoname, photow, photoh);
		fly(photo, targetidx, delay);
		var spreadDOM = $(".spread-div[data-spread='" + targetidx + "']").find('.spread');
		spreadDOM[0].scrollIntoView(false);
		photo[0].scrollIntoView(false);

		//	photo.parent().addClass("used");
		bookstate[targetidx].matchingtpls = undefined;
		var ismatch = rematch(targetidx);
		if (!ismatch)
			handleUndo();
		setTimeout(function () {
			if (ismatch) {
				populateSpread(targetidx, true);
				photogrid.refreshItems().layout();
			}
		}, delay);
		updateUsed();
	}

