	// return template (a permutation of ctpl)
	// to match photos in cimg (horizontal photos in horizontal apertures etc)
	function matchUp(img, ctpl, docw, doch) {
		// console.log("matchUp: docw, doch = " + docw + ", " + doch);
		var cimg = img.slice(0);
		var besttpl = [];
		var bestimg = [];
		var rest = [];
		while (cimg.length > 0) {
			var img = cimg.shift();
			var iort = orientation(img.w, img.h);
			// console.log(img.src + " has orientation " + iort);
			var exact = false;
			for (k = 0; k < ctpl.length; k++) {
				var tort = orientation(docw * ctpl[k].w, doch * ctpl[k].h);
				// console.log("comparing with aperture " + k + " with orientation " + tort);
				if (iort == tort) { // take it
					exact = true;
					// console.log("exact match");
					besttpl.push({
						t: ctpl[k].t,
						l: ctpl[k].l,
						w: ctpl[k].w,
						h: ctpl[k].h,
						z: ctpl[k].z ? ctpl[k].z : 0,
					});
					bestimg.push(img);
					ctpl.splice(k, 1);
					break;
				} else {
					// console.log("not exact match");
				}
			}
			if (!exact)
				rest.push(img);
		}

		try {
			while (rest.length > 0) {
				var img = rest.shift();
				var okhole = ctpl.shift();
				besttpl.push({
					t: okhole.t,
					l: okhole.l,
					w: okhole.w,
					h: okhole.h,
					z: okhole.z ? okhole.z : 0
				});
				bestimg.push(img);
			}
		} catch (e) {
			console.log("oops!");
			return;
		}

		//	    return besttpl;
		return { "cimg": bestimg, "ctpl": besttpl };
	}

	function populateIcon(tplno, spreadidx) {
		var icon = $(".tplicon[data-tplno=" + tplno + "]").find('.tplcontent');
		var resetp = false;
		var spread = bookstate[spreadidx];
		if (!spread || !spread["photos"])
			return;
		var docw = icon.parent().width();
		var doch = icon.parent().height();
		var cimg = deepCopyPhotos(spread);
		var ctpl = tpl[tplno].slice(0);
		var r = matchUp(cimg, ctpl, docw, doch);
		cimg = r.cimg;
		ctpl = r.ctpl;
		icon.empty();
		for (var i = 0; i < ctpl.length; i++) {
			var tx0 = ctpl[i].l / 100;
			var ty0 = ctpl[i].t / 100;
			var tx1 = tx0 + ctpl[i].w / 100;
			var ty1 = ty0 + ctpl[i].h / 100;
			var tz = ctpl[i].z;
			var t_left = (docw * tx0);
			var t_top = (doch * ty0);
			var t_width = (docw * (tx1 - tx0));
			var t_height = (doch * (ty1 - ty0));
			var di_parent = $("<div>").attr({ "class": "tplphoto" }).appendTo(icon);
			var di = $("<img>");
			di.attr("src", "../albums/" + 10840 + "/photos/thumbs/" + cimg[i].src);
			di.appendTo(di_parent);
			t_left = tx0 * docw;
			t_top = ty0 * doch;
			t_width = (tx1 - tx0) * docw;
			t_height = (ty1 - ty0) * doch;
			tz = ctpl[i].z;
			var sx = t_height / cimg[i].h;
			var sy = t_width / cimg[i].w;
			var ss = Math.max(sx, sy);
			dx = -(t_width - ss * cimg[i].w) / 2;
			dy = -(t_height - ss * cimg[i].h) / 2;
			cimg[i].cx = cimg[i].w / 2;
			cimg[i].cy = cimg[i].h / 2;
			cimg[i].dx = dx / docw;
			cimg[i].dy = dy / doch;
			cimg[i].sw = t_width / docw;
			cimg[i].sh = t_height / doch;
			cimg[i].zm = Math.max(ss * 100 / docw, ss * 100 / doch);

			di.css({
				"position": "absolute",
				"cursor": "move",
				"transform-origin": "0px 0px",
				"transform": "translate(" + (-dx) + "px, " + (-dy) + "px) scale(" + ss + ")",
			});

			di_parent.css({
				overflow: "hidden",
				position: "absolute",
				top: t_top,
				left: t_left,
				width: t_width,
				height: t_height,
				"z-index": tz,
			});
		}
	}

