	function slurpTemplatesAux(filelist, i, n, postfn) {
		if (i >= n) { /* done */
			// drawTemplates();
			console.log("loaded " + tpl.length + " templates");
			if (postfn)
				postfn();
			return;
		}

		var filename = filelist[i];
		var userid = 21;
		$.post("../scripts/slurp-templates.php", {
			"userid": userid,
			"filenames": [filename],
		}).done(function (json) {
			//        console.log("for " + filename + ", I read:");
			//        console.log(json);
			if (json == "")
				swal({
					title: "No templates defined for " + filename,
					text: "Please notify kjell@irstafoto.se",
					confirmButtonText: "OK"
				});
			json += "[" + json + "]";
			try {
				var segment = eval(json);
			} catch (e) {
				swal({
					title: "Error evaluating " + filename,
					text: "Please notify kjell@irstafoto.se",
					confirmButtonText: "OK"
				});
			}
			genTplIcons(segment, tpl.length, filename);
			tpl = tpl.concat(segment);
			slurpTemplatesAux(filelist, i + 1, n, postfn);
		});
	}

	function slurpTemplates(filelist, postfn) {
		$("#template-icons").empty();
		tpl = [];
		slurpTemplatesAux(filelist, 0, filelist.length, postfn);
	}

