	// return string of used photos
	// suffix can be ".jpg", ".DNG" or whatever you want - it's added to the end of every filename
	// sep can be "," or " " - it's added between each filename
	function usedPhotos(suffix, sep) {
		suffix = suffix || "";
		sep = sep || ",";
		console.log("suffix = " + suffix + ", sep = " + sep);
		var aused = [];
		var skeys = Object.keys(bookstate);
		var nphotos = 0;
		for (var i = 0; i < skeys.length; i++) {
			var cimg = bookstate[skeys[i]]["photos"];
			for (var j = 0; j < cimg.length; j++)
				if (-1 == cimg[0].src.indexOf("$RAD"))
					nphotos++;
		}
		for (var i = 0; i < skeys.length; i++) {
			var cimg = bookstate[skeys[i]]["photos"];
			for (var j = 0; j < cimg.length; j++) {
				var f = decodeURIComponent(cimg[j].src);
				f = basename_nosuffix(f) + suffix;
				if (-1 == cimg[0].src.indexOf("$RAD"))
					aused.push(f);
			}
		}
		aused.sort();
		var collator = new Intl.Collator(undefined, { numeric: true, sensitivity: 'base' });
		aused.sort(collator.compare)

		var used = "";
		for (var a in aused)
			used += aused[a] + sep + " ";


		return used.slice(0, - (1 + sep.length));
	}

	function nrUsedPhotos() {
		var skeys = Object.keys(bookstate);
		var nphotos = 0;
		for (var i = 0; i < skeys.length; i++) {
			var cimg = bookstate[skeys[i]]["photos"];
			for (var j = 0; j < cimg.length; j++)
				if (-1 == cimg[0].src.indexOf("$RAD"))
					nphotos++;
		}
		return nphotos;
	}

