	function detectVerticalSquash(img) {
		var iw = img.naturalWidth, ih = img.naturalHeight;
		var canvas = document.createElement('canvas');
		canvas.width = 1;
		canvas.height = ih;
		var ctx = canvas.getContext('2d');
		ctx.drawImage(img, 0, 0);
		var data = ctx.getImageData(0, 0, 1, ih).data;
		// search image edge pixel position in case it is squashed vertically.
		var sy = 0;
		var ey = ih;
		var py = ih;
		while (py > sy) {
			var alpha = data[(py - 1) * 4 + 3];
			if (alpha === 0) {
				ey = py;
			} else {
				sy = py;
			}
			py = (ey + sy) >> 1;
		}
		var ratio = (py / ih);
		return (ratio === 0) ? 1 : ratio;
	}


	/* credits to stomita for fixing the iOS bug */
	function drawImageIOSFix(ctx, img, sx, sy, sw, sh, dx, dy, dw, dh, styles, coverp) {

		var vertSquashRatio = detectVerticalSquash(img);
		var spreadTNW = ctx.canvas.width;
		var spreadTNH = ctx.canvas.height;
		ctx.save();

		if (styles && styles["opacity"])
			ctx.globalAlpha = parseFloat(styles["opacity"]);

		if (styles && styles["border-radius"] > 0) { /* corner radius */
			// console.log("drawimage: border-radius: " + styles["border-radius"]);
			var radius = styles["border-radius"] / 3;
			ctx.globalCompositeOperation = 'source-atop';
			ctx.beginPath();
			ctx.moveTo(dx + radius, dy);
			ctx.lineTo(dx + dw - radius, dy);
			ctx.quadraticCurveTo(dx + dw, dy, dx + dw, dy + radius);
			ctx.lineTo(dx + dw, dy + dh - radius);
			ctx.quadraticCurveTo(dx + dw, dy + dh, dx + dw - radius, dy + dh);
			ctx.lineTo(dx + radius, dy + dh);
			ctx.quadraticCurveTo(dx, dy + dh, dx, dy + dh - radius);
			ctx.lineTo(dx, dy + radius);
			ctx.quadraticCurveTo(dx, dy, dx + radius, dy);
			ctx.closePath();
			ctx.clip();
		}

		ctx.drawImage(img, sx, sy, sw, sh, dx, dy, dw, dh / vertSquashRatio);

		if (styles && parseFloat(styles["saturation"], 10) == 0) {  /* Black & White */
			// console.log("drawimage B&W: " + styles["saturation"]);
			var imageData = ctx.getImageData(Math.round(dx), Math.round(dy), Math.round(dw), Math.round(dh));
			var pixelData = imageData.data;
			var bytesPerPixel = 4;
			for (var y = 0; y < dh; y++) {
				for (var x = 0; x < dw; x++) {
					var startIdx = (y * bytesPerPixel * Math.floor(dw)) + (x * bytesPerPixel);
					var red = pixelData[startIdx];
					var green = pixelData[startIdx + 1];
					var blue = pixelData[startIdx + 2];
					var grayScale = (red * 0.3) + (green * 0.59) + (blue * .11);
					pixelData[startIdx] = grayScale;
					pixelData[startIdx + 1] = grayScale;
					pixelData[startIdx + 2] = grayScale;
				}
			}
			ctx.putImageData(imageData, dx, dy);
		}

		/* border */
		if (styles && styles["border-thickness"] > 0) {
			ctx.beginPath();
			ctx.rect(dx + 0.5, dy + 0.5, dw - 1, dh - 1);
			ctx.lineWidth = styles["border-thickness"] * spreadTNH / 800;
			ctx.strokeStyle = styles["border-color"];
			ctx.stroke();
		}

		// Folio matted albums: don't show what's behind the mat
		if (!coverp && radtype == "Folio" && typeof typ !== 'undefined' && typ.match(/matte/i)) {
			var k = 3 / 300;
			if (typ == "matte10x10")
				k = 3 / 500;
			else if (typ == "matte12x12")
				k = 3 / 600;

			var w = ctx.canvas.clientWidth;
			if (!w) // not in DOM yet
				w = ctx.canvas.width;
			var delta = w * k;
			ctx.beginPath();
			ctx.rect(dx + delta - 1, dy + delta - 1, dw - 2 * delta + 2, dh - 2 * delta + 2);
			ctx.lineWidth = 2 * delta;
			ctx.strokeStyle = "#eee";
			//	ctx.strokeStyle = "rgba(192, 192, 192, 0.5)";
			ctx.stroke();
		}

		ctx.restore();
	}



	function drawCommentSpread(canvas, idx, comments, commentstate) {

		function drawComments() {
			$("#flipbook-comments").empty();
			for (c in comments) {
				if (comments[c].spread == parseInt(idx, 10)) {
					pprint(comments[c]);
					var xL = docw * comments[c].x;
					var yL = doch * comments[c].y;
					var diam = 30;
					drawCircle(context, xL, yL, diam / 2);
					drawCenterText(context, xL, yL + diam / 8, c, 9);
					$("#flipbook-comments").append('<span class="badge badge-pill badge-warning">'
						+ c + "</span> " + comments[c].str + "<br>");
				}
			}
		}

		if (!commentstate[idx])
			return;
		var docw = canvas.width;
		var doch = canvas.height;
		var tpls = commentstate[idx]["template"];
		var cimg = commentstate[idx]["photos"];
		var cstyles = commentstate[idx]["styles"];
		var ctxt = commentstate[idx]["text"];

		var bg = commentstate[idx]["bg"];
		var context = canvas.getContext('2d');
		context.rect(0, 0, canvas.width, canvas.height);
		context.fillStyle = "#" + bg;
		context.fill();

		var imgobj = {};
		var n = 1;
		var SW = canvas.width / 100;
		var SH = canvas.height / 100;

		drawComments(); // in case there are no images


		for (var i = 0; i < cimg.length; i++) {
			imgobj[i] = new Image();
			imgobj[i].onload = function (e) {
				if (n++ >= cimg.length) {
					for (var j = 0; j < cimg.length; j++) {
						if (cimg[j]["w"] == 0)
							cimg[j]["w"] = imgobj[j].width;
						if (cimg[j]["h"] == 0)
							cimg[j]["h"] = imgobj[j].height;
						var sx = cimg[j]["w"] / (cimg[j]["sw"] * docw);
						var sy = cimg[j]["h"] / (cimg[j]["sh"] * doch);
						var s = Math.min(sx, sy);
						var sourceX = Math.max(0, cimg[j]["dx"] * s * docw);
						var sourceY = Math.max(0, cimg[j]["dy"] * s * doch);
						var sourceWidth = tpls[j]["w"] * s * (docw / 100);
						var sourceHeight = tpls[j]["h"] * s * (doch / 100);
						var destX = tpls[j]["l"] * SW;
						var destY = tpls[j]["t"] * SH;
						var destWidth = tpls[j]["w"] * SW;
						var destHeight = tpls[j]["h"] * SH;

						drawImageIOSFix(context, imgobj[j],
							//context.drawImage(imgobj[j],
							sourceX, sourceY,
							Math.min(sourceWidth, imgobj[j].width - sourceX),
							Math.min(sourceHeight, imgobj[j].height - sourceY),
							destX, destY,
							destWidth, destHeight, (cstyles ? cstyles[j] : undefined));
					}
					drawComments();
				}
			}

			imgobj[i].src = "../albums/" + albumid + "/photos/thumbs/" + cimg[i].src;
		}

		// drawText(canvas, ctxt); // fixme
	}

