	function albumcomment(idx) {
		// cmtfile already contains selected comment version, e.g., "comments-20180828194150.oad"
		// now read contents of this file, along with the album project with the same date
		var comment_fullfile = "../../albums/" + albumid + "/spreads/" + cmtfile;
		var cmtstate_fullfile = comment_fullfile.replace("comments", "album");
		$.post("./scripts/read.php", { 'F': comment_fullfile })
			.done(function (json1) {
				if (json1.substr(0, 4) == "CANT") {
					alert("Error: can't read comment file " + cmtfile);
					comments = {};
				} else {
					comments = JSON.parse(json1);
					$.post("./scripts/read.php", { 'F': cmtstate_fullfile }).done(function (json2) {
						if (json2.substr(0, 4) == "CANT") {
							alert("Error: can't read project file " + cmtstate_fullfile);
							comments = {};
						} else {
							commentstate = JSON.parse(json2);
							var n = nrspreads(commentstate);
							$("#comment-spreadnr").text(idx);
							$("#comment-prev").text(pagefmt(Math.max(parseInt(idx, 10) - 1, 1)));
							$("#comment-next").text(pagefmt(Math.min(parseInt(idx, 10) + 1, n)));
							// disable all spread bubbles, enable spread bubble for idx
							$(".spread-comment").removeClass("fa-comment").addClass("fa-comment-o");
							$(".spread-div[data-spread='" + idx + "']")
								.find('.spread-comment')
								.removeClass("fa-comment-o").addClass("fa-comment");
							albumcomment_main(idx, comments, commentstate);
						}
					});
				}

			});
	}

